uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float smoothing;
uniform float threshold;
uniform float amp;
uniform float alpha;
layout(color) uniform half4 color2;
layout(color) uniform half4 color1;
uniform float blendMode;
uniform float fix;
uniform float newMode;
uniform float invert;
        const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
        void amzRender() {
            float2 st = amzScreenNorm();
            float2 fragSize = float2(1.)/getTexSize((screen.zw/1.0)) * smoothing;
            float w = dot(float3(1.),amzTexture(0, float2(amzScreenNorm().x - fragSize.x, amzScreenNorm().y) ).rgb*luminanceWeighting);
            float e = dot(float3(1.),amzTexture(0, float2(amzScreenNorm().x + fragSize.x, amzScreenNorm().y) ).rgb*luminanceWeighting);
            float n = dot(float3(1.),amzTexture(0, float2(amzScreenNorm().x, amzScreenNorm().y + fragSize.y) ).rgb*luminanceWeighting);
            float s = dot(float3(1.),amzTexture(0, float2(amzScreenNorm().x, amzScreenNorm().y - fragSize.y) ).rgb*luminanceWeighting);
            float nw = dot(float3(1.),amzTexture(0, float2(amzScreenNorm().x - fragSize.x, amzScreenNorm().y + fragSize.y) ).rgb*luminanceWeighting);
            float ne = dot(float3(1.),amzTexture(0, float2(amzScreenNorm().x + fragSize.x, amzScreenNorm().y + fragSize.y) ).rgb*luminanceWeighting);
            float sw = dot(float3(1.),amzTexture(0, float2(amzScreenNorm().x - fragSize.x, amzScreenNorm().y - fragSize.y) ).rgb*luminanceWeighting);
            float se = dot(float3(1.),amzTexture(0, float2(amzScreenNorm().x + fragSize.x, amzScreenNorm().y - fragSize.y) ).rgb*luminanceWeighting);
            float v = nw * 3. + n * 10. + ne * 3. + sw * -3. + s * -10. + se * -3.;
            float h = nw * -3. + w * -10. + sw * -3. + ne * 3. + e * 10. + se * 3.;
            float4 texColor = amzTexture(0, amzScreenNorm());
            if ((fix>0.5)) { v *= v; h *= h; }
            v *= amp;
            h *= amp;
           float g = clamp(sqrt(h*h + v*v)-threshold, 0., 1.);
            float edge = sqrt(h*h + v*v);
            float4 keyColor = float4(1,1,1,1);
            float4 colour = float4(edge*keyColor.r, edge*keyColor.g, edge*keyColor.b, 1.0);
            float4 edgeLine = clamp(colour-threshold,0.0,1.0)*1.0/(1.0-threshold);
            float4 edgeNew = float4(1.-edgeLine.r, 1.-edgeLine.g, 1.-edgeLine.b, edgeLine.a ) * texColor.a;
            float4 edgeOld;
            float4 edgeNewFinal;
            const float3 luminanceWeighting = float3(0.2126, 0.7152, 0.0722);
            float4 edgeFinal;
            float luminance = dot(edgeNew.rgb, luminanceWeighting);
            edgeFinal = mix(color1,color2,luminance)*edgeNew.a;
            float4 xnxx = edgeFinal;
            if( (invert>0.5) ) {
            edgeNewFinal = float4( 1.-xnxx.r, 1.-xnxx.g, 1.-xnxx.b, xnxx.a ) * texColor.a;
            edgeOld = float4(g,g,g,1.) * texColor; }
            else {
            edgeNewFinal = edgeFinal * texColor.a;
            edgeOld = float4(1.-g,1.-g,1.-g,1.) * texColor.a; }
            float4 factor = (newMode>0.5)? edgeNewFinal : edgeOld;
        float4 resultfinal;
        if( int(blendMode)==0 ) {
            resultfinal = factor * texColor.a;
        } else if( int(blendMode)==1 ) {
            float4 c = factor + float4(1.)*(1.-factor.a);
            resultfinal = float4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( int(blendMode)==2 ) {
            resultfinal = float4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }
     amzOutput = mix(texColor, resultfinal, alpha);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
